APX.cz = {"country":{"name":"Czechia","tagline":"Moravian cellar lanes, Pálava limestone and the Elbe hills of Bohemia: a wine culture older than the country's beer fame suggests.","classification":"Czech wine follows EU categories: víno (wine), zemské víno (PGI, from the České or Moravské regions), jakostní víno (quality wine from a region or subregion) and jakostní víno s přívlastkem (Prädikat wine: kabinetní víno, pozdní sběr, výběr z hroznů, výběr z bobulí, výběr z cibéb, ledové víno and slámové víno), defined by sugar at harvest. The EU register holds Čechy and Morava, the six subregions, and three local PDOs: Znojmo (the VOC), Šobes and Novosedelské Slámové víno.\n\nVOC (víno originální certifikace) is a growers' appellation for a defined area, with its own varieties, styles and tasting control, closer to the Austrian DAC than to the Prädikat system. The 13 VOCs are Znojmo (2009), Mikulov and Modré Hory (2011), Pálava (2012), Blatnice (2013), Valtice and Mělník (2015), Slovácko and Hustopečsko (2016), Kraví hora and Bzenec (2017), Mutěnice (2018) and Velké Pavlovice (2019)."},"regions":[{"name":"Morava","slug":"morava","tagline":"South Moravia: cellar lanes, loess and Pálava limestone on the Austrian border.","ids":["cz-blatnice","cz-bzenec","cz-hustopecsko","cz-kravi-hora","cz-mikulov","cz-mikulovska","cz-modre-hory","cz-morava","cz-mutenice","cz-novosedelske-slamove-vino","cz-palava","cz-slovacko","cz-slovacka","cz-valtice","cz-velkopavlovicka","cz-velke-pavlovice","cz-znojemska","cz-znojmo","cz-sobes"]},{"name":"Čechy","slug":"echy","tagline":"A sliver of vines on the Elbe, where Czech wine began in legend.","ids":["cz-litomericka","cz-melnicka","cz-melnik","cz-cechy"]}],"items":{"cz-blatnice":{"name":"Blatnice","cat":"VOC","region":"Morava","subregion":"Slovácká","created":"2013","styles":["white","red"],"grapes":"Defined by the VOC association","summary":"VOC for Blatnice pod Svatým Antonínkem and nearby villages in Slovácko, best known for a traditional white blend. Like all VOCs it is run by a local growers' association that fixes varieties, style and a tasting check; it sits inside the subregion PDO rather than having its own EU registration.","rslug":"morava"},"cz-bzenec":{"name":"Bzenec","cat":"VOC","region":"Morava","subregion":"Slovácká","created":"2017","styles":["white","red"],"grapes":"Defined by the VOC association","summary":"VOC for Bzenec, whose sandy soils have long been famous for Riesling (Ryzlink rýnský). Like all VOCs it is run by a local growers' association that fixes varieties, style and a tasting check; it sits inside the subregion PDO rather than having its own EU registration.","rslug":"morava"},"cz-cechy":{"name":"Čechy","cat":"PDO","region":"Čechy","created":"2006 (EU reg.)","styles":["white","red"],"grapes":"Müller-Thurgau, Riesling, Saint Laurent, Pinot Noir","summary":"The regional PDO for Bohemia's small vineyards, covering 67 municipalities in the EU register along the Elbe, Vltava and Ohře and in Prague.","contains":["Mělnická","Litoměřická"],"rslug":"echy"},"cz-hustopecsko":{"name":"Hustopečsko","cat":"VOC","region":"Morava","subregion":"Velkopavlovická","created":"2016","styles":["white","red"],"grapes":"Defined by the VOC association","summary":"VOC for the area around Hustopeče, a town of almond orchards and wine. Like all VOCs it is run by a local growers' association that fixes varieties, style and a tasting check; it sits inside the subregion PDO rather than having its own EU registration.","rslug":"morava"},"cz-kravi-hora":{"name":"Kraví hora","cat":"VOC","region":"Morava","subregion":"Velkopavlovická","created":"2017","styles":["white","red"],"grapes":"Defined by the VOC association","summary":"VOC for the Kraví hora hill at Bořetice, a sunny loess and sandstone slope with a famous cellar village and lookout tower. Like all VOCs it is run by a local growers' association that fixes varieties, style and a tasting check; it sits inside the subregion PDO rather than having its own EU registration.","rslug":"morava"},"cz-litomericka":{"name":"Litoměřická","cat":"PDO","region":"Čechy","subregion":"Litoměřická","created":"2006 (EU reg.)","styles":["white","red"],"grapes":"Müller-Thurgau, Riesling, Gewürztraminer, Pinot Blanc, Saint Laurent","summary":"The northern Bohemian subregion along the Elbe around Litoměřice, Velké Žernoseky, Roudnice nad Labem and Most, in the volcanic landscape of the České středohoří hills. Velké Žernoseky's deep cellars are among the oldest wine cellars in Bohemia.","terroir":"Basalt, volcanic tuff, sandstone and marl on Elbe slopes.","producers":["Vinařství Žernosecké","Lobkowicz Roudnice","Vinařství Johann W"],"rslug":"echy"},"cz-melnicka":{"name":"Mělnická","cat":"PDO","region":"Čechy","subregion":"Mělnická","created":"2006 (EU reg.)","styles":["white","red"],"grapes":"Müller-Thurgau, Riesling, Pinot Noir, Saint Laurent, Pinot Blanc","summary":"The subregion around Mělník at the confluence of the Elbe and Vltava, including Prague's historic vineyards. Mělník's Lobkowicz château winery and its terraced slopes above the rivers are the emblem of Bohemian wine, linked to St. Ludmila and Charles IV.","terroir":"Sandstone and marl slopes at the river confluence.","producers":["Château Mělník (Lobkowicz)","Vinařství Kraus"],"nerd_note":"Tradition credits Charles IV with bringing Burgundian vines to Mělník; Pinot Noir is still a local speciality.","rslug":"echy"},"cz-melnik":{"name":"Mělník","cat":"VOC","region":"Čechy","subregion":"Mělnická","created":"2015","styles":["white","red"],"grapes":"Defined by the VOC association","summary":"Bohemia's only VOC, for the historic vineyards around Mělník on the Elbe and Vltava. Like all VOCs it is run by a local growers' association that fixes varieties, style and a tasting check; it sits inside the subregion PDO rather than having its own EU registration.","rslug":"echy"},"cz-mikulov":{"name":"Mikulov","cat":"VOC","region":"Morava","subregion":"Mikulovská","created":"2011","styles":["white","red"],"grapes":"Defined by the VOC association","summary":"VOC for the area around Mikulov and the Pálava hills, focused on dry whites such as Welschriesling, Grüner Veltliner, Riesling and the Pinots. Like all VOCs it is run by a local growers' association that fixes varieties, style and a tasting check; it sits inside the subregion PDO rather than having its own EU registration.","rslug":"morava"},"cz-mikulovska":{"name":"Mikulovská","cat":"PDO","region":"Morava","subregion":"Mikulovská","created":"2006 (EU reg.)","styles":["white","red","sweet"],"grapes":"Welschriesling, Grüner Veltliner, Riesling, Pinot Gris, Chardonnay, Pálava","summary":"Mikulovská surrounds the Pálava hills, a limestone ridge rising sharply from the plain south of Brno, with the towns of Mikulov and Valtice and villages such as Dolní Dunajovice, Pavlov and Novosedly. Its Jurassic limestone and loess give the most structured Czech whites, especially Welschriesling, Riesling and Pinot Gris. The subregion is also the centre of Moravia's natural-wine movement.","terroir":"Jurassic limestone of the Pálava hills, loess and sand; warm and dry.","producers":["Sonberk","Mikrosvín Mikulov","Vinařství Volařík","Nové Vinařství","Richard Stávek","Milan Nestarec"],"nerd_note":"The Pálava hills are a UNESCO biosphere reserve whose rare steppe flora grows between the vines.","contains":["Novosedelské Slámové víno"],"rslug":"morava"},"cz-modre-hory":{"name":"Modré Hory","cat":"VOC","region":"Morava","subregion":"Velkopavlovická","created":"2011","styles":["white","red"],"grapes":"Defined by the VOC association","summary":"'Blue Mountains', a VOC for red wines from villages around Bořetice, Kobylí, Němčičky and Velké Pavlovice, with Frankovka, Saint Laurent, Zweigelt and Portugieser. Like all VOCs it is run by a local growers' association that fixes varieties, style and a tasting check; it sits inside the subregion PDO rather than having its own EU registration.","rslug":"morava"},"cz-morava":{"name":"Morava","cat":"PDO","region":"Morava","created":"2006 (EU reg.)","styles":["white","red","rose","sparkling","sweet"],"grapes":"Grüner Veltliner, Welschriesling, Müller-Thurgau, Riesling, Saint Laurent, Blaufränkisch and many others","summary":"The regional PDO for Moravia, covering 301 municipalities in the EU register and about 95 percent of Czech vineyards. It is used for quality and Prädikat wine from anywhere in the four Moravian subregions.","contains":["Znojemská","Mikulovská","Velkopavlovická","Slovácká"],"rslug":"morava"},"cz-mutenice":{"name":"Mutěnice","cat":"VOC","region":"Morava","subregion":"Slovácká","created":"2018","styles":["white","red"],"grapes":"Defined by the VOC association","summary":"VOC for Mutěnice, a large wine village with a viticulture research station and cellar lanes. Like all VOCs it is run by a local growers' association that fixes varieties, style and a tasting check; it sits inside the subregion PDO rather than having its own EU registration.","rslug":"morava"},"cz-novosedelske-slamove-vino":{"name":"Novosedelské Slámové víno","cat":"PDO","region":"Morava","subregion":"Mikulovská","created":"2011 (EU reg.)","styles":["sweet"],"grapes":"Many varieties (white and red)","summary":"A PDO for straw wine (slámové víno) from the village of Novosedly near Mikulov, made from grapes dried on straw or hung for months before pressing, giving intensely sweet wines. Novosedly is one of the largest wine villages in Moravia (about 421 ha).","terroir":"Loess and sand below the Pálava hills.","nerd_note":"One of very few straw-wine PDOs in Europe.","rslug":"morava"},"cz-palava":{"name":"Pálava","cat":"VOC","region":"Morava","subregion":"Mikulovská","created":"2012","styles":["white","red"],"grapes":"Defined by the VOC association","summary":"VOC for wines from the villages around the Pálava limestone ridge (Pavlov, Dolní Věstonice, Perná, Bavory, Klentnice), known for structured whites. Like all VOCs it is run by a local growers' association that fixes varieties, style and a tasting check; it sits inside the subregion PDO rather than having its own EU registration.","rslug":"morava"},"cz-slovacka":{"name":"Slovácká","cat":"PDO","region":"Morava","subregion":"Slovácká","created":"2006 (EU reg.)","styles":["white","red","rose"],"grapes":"Riesling, Welschriesling, Müller-Thurgau, Grüner Veltliner, Saint Laurent, Blaufränkisch","summary":"The eastern Moravian subregion (Moravian Slovakia), around Mutěnice, Bzenec, Strážnice, Blatnice and Uherské Hradiště, a folk-culture landscape of painted cellars and wine festivals. Sandy soils at Bzenec give famous Riesling, and the slopes of the White Carpathians near Blatnice give fresh whites.","terroir":"Sand, loess and Carpathian flysch; slightly wetter and cooler near the hills.","producers":["Vinařství Jakubík","Vinařství Petrák","Vinařství Šebela"],"nerd_note":"Blatnice's St. Anthony chapel on its hill is a pilgrimage site above the vines.","rslug":"morava"},"cz-slovacko":{"name":"Slovácko","cat":"VOC","region":"Morava","subregion":"Slovácká","created":"2016","styles":["white","red"],"grapes":"Defined by the VOC association","summary":"VOC for wines from the Slovácko subregion's villages, emphasising local character. Like all VOCs it is run by a local growers' association that fixes varieties, style and a tasting check; it sits inside the subregion PDO rather than having its own EU registration.","rslug":"morava"},"cz-sobes":{"name":"Šobes / Šobeské víno","cat":"PDO","region":"Morava","subregion":"Znojemská","created":"2011 (EU reg.)","area_ha":13,"styles":["white","red"],"grapes":"Riesling, Sauvignon Blanc, Grüner Veltliner, Pinot Blanc, Pinot Gris, Welschriesling, Pálava, Gewürztraminer, Pinot Noir","summary":"Šobes is a single vineyard of about 13 hectares on a south-facing slope inside a meander of the Dyje river in the Podyjí National Park near Znojmo, reachable by foot or boat. Often called one of the oldest vineyards in central Europe, it has its own EU PDO (2011) and gives fine Riesling and Sauvignon from gneiss and granite.","terroir":"Weathered gneiss and granite on a sun-trap slope enclosed by the river canyon.","producers":["Znovín Znojmo"],"nerd_note":"The vineyard lies opposite the Austrian Thayatal National Park across the river.","rslug":"morava"},"cz-valtice":{"name":"Valtice","cat":"VOC","region":"Morava","subregion":"Mikulovská","created":"2015","styles":["white","red"],"grapes":"Defined by the VOC association","summary":"VOC for the Valtice area, seat of the Liechtenstein château and the National Wine Salon. Like all VOCs it is run by a local growers' association that fixes varieties, style and a tasting check; it sits inside the subregion PDO rather than having its own EU registration.","rslug":"morava"},"cz-velke-pavlovice":{"name":"Velké Pavlovice","cat":"VOC","region":"Morava","subregion":"Velkopavlovická","created":"2019","styles":["white","red"],"grapes":"Defined by the VOC association","summary":"VOC for Velké Pavlovice, the red-wine and apricot town of central Moravia. Like all VOCs it is run by a local growers' association that fixes varieties, style and a tasting check; it sits inside the subregion PDO rather than having its own EU registration.","rslug":"morava"},"cz-velkopavlovicka":{"name":"Velkopavlovická","cat":"PDO","region":"Morava","subregion":"Velkopavlovická","created":"2006 (EU reg.)","styles":["red","white","rose"],"grapes":"Blaufränkisch, Saint Laurent, Zweigelt, André, Pinot Noir, Welschriesling, Grüner Veltliner","summary":"The central Moravian subregion around Velké Pavlovice, Velké Bílovice (the largest wine village in the country, about 766 ha), Hustopeče, Čejkovice, Bořetice and Kobylí. Rolling loess hills with apricot orchards make it the red-wine heart of Czechia, home of Frankovka, Saint Laurent and the André crossing, bred here in 1961.","terroir":"Deep loess, sand and marl on rolling hills; warm summers.","producers":["Vinařství Gotberg","Vinselekt Michlovský","Vinařství Stapleton & Springer","Vinařství Krist","Vinařství Kraví hora","Vinařství Proqin"],"nerd_note":"The red crossing André (Blaufränkisch x Saint Laurent) was bred in this part of Moravia and remains a local favourite.","rslug":"morava"},"cz-znojemska":{"name":"Znojemská","cat":"PDO","region":"Morava","subregion":"Znojemská","created":"2006 (EU reg.)","styles":["white","red"],"grapes":"Grüner Veltliner, Sauvignon Blanc, Riesling, Müller-Thurgau, Pinot Blanc","summary":"The western Moravian subregion around Znojmo on the Dyje (Thaya), facing Austria's Weinviertel across the border. Granite and gneiss in the Dyje canyon and loess elsewhere give aromatic, crisp whites, especially Grüner Veltliner, Sauvignon Blanc and Riesling. It includes the Šobes vineyard and the villages of Hnanice, Nový Šaldorf, Vrbovec (344 ha) and Dobšice.","terroir":"Granite, gneiss and loess; the coolest and most aromatic of the Moravian subregions.","producers":["Znovín Znojmo","Lahofer","Vinařství Waldberg","Ivan Váňa","Vinařství Lahofer","Dobrá Vinice"],"nerd_note":"Znojmo's medieval underground labyrinth was used for wine storage.","contains":["Znojmo","Šobes / Šobeské víno"],"rslug":"morava"},"cz-znojmo":{"name":"Znojmo","cat":"VOC","region":"Morava","subregion":"Znojemská","created":"2009 (first VOC); EU reg. 2011","styles":["white"],"grapes":"Grüner Veltliner, Riesling, Sauvignon Blanc","summary":"The first Czech VOC (2009) and the only one registered separately as an EU PDO (2011). It covers 22 villages around Znojmo and allows only Veltlínské zelené, Ryzlink rýnský and Sauvignon, in a fresh, aromatic dry style. The Znojmo growers' initiative became the model for later VOCs.","terroir":"Granite, gneiss and loess in the Dyje valley.","producers":["Znovín Znojmo","Lahofer","Vinařství Waldberg"],"nerd_note":"The EU register caps VOC Znojmo at 12,000 kg of grapes per hectare.","rslug":"morava"}}};
